INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102831,0,0,'%s calls out to nearby creatures for aid.',16,0,100.0,0,0,0,107617,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102839,0,0,'|TInterface\\Icons\\ability_fomor_boss_shout:20|t%s begins a |cFFFF0404|Hspell:209748|h[Deafening Roar]|h|r. Stop casting!',41,0,100.0,0,0,0,108810,0,'LegionCore');
